class Solution {
public:
    ListNode* swapNodes(ListNode* head, int k) {
        ListNode* first = head;
        for (int s = 1; s < k; s++) first = first->next;
        ListNode* scout = first;
        ListNode* second = head;
        while (scout->next) {
            scout = scout->next;
            second = second->next;
        }
        swap(first->val, second->val);
        return head;
    }
};
